import{z as o,x as B,o as E,c as p,q as i,j as s,D as t,d as e,s as l,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"三张表怎么连","description":"","frontmatter":{"title":"三张表怎么连","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/three-statements-link.md","filePath":"quant/three-statements-link.md","lastUpdated":1791413859000}'),d={name:"quant/three-statements-link.md"};function m(u,a,c,h,f,C){const r=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=i('<h1 id="三张表怎么连" tabindex="-1">三张表怎么连 <a class="header-anchor" href="#三张表怎么连" aria-label="Permalink to &quot;三张表怎么连&quot;">​</a></h1><div class="epigraph"><p>利润表上的净利润，经留存收益滚进资产负债表；现金流量表则从净利润出发，用非现金项目与营运资本变动把它翻译成现金。</p><footer>—— 据 Penman, Financial Statement Analysis and Security Valuation, 第 3–5 章整理</footer></div><p>上一课<a href="/quant/variance-reduction">方差缩减</a>把随机分析课程收到「同一期望、更少路径」。定价数学至此可算。缺口换成另一类对象：可交易的不是一条模拟路径，而是一张<strong>当时可观测的公司状态表</strong>。本课是「财务数据与基本面」第一课；后课默认三张表各自记什么、怎样勾稽，不再从复式记账入门。本课只钉身份与期间/时点，不钉可用日期——那是后两课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/variance-reduction">方差缩减</a>处理的是风险中性期望的估计噪声。进入基本面后，噪声来源换成会计身份是否闭合、字段是否对上同一家公司的同一报告期。利润表给期间绩效，资产负债表给时点存量，现金流量表解释现金从哪来、到哪去。三张表若各存各的，后面应计拆分、账面市值、Fama–French 的账面权益都会张冠李戴。</p><p>缺口不是「会计是什么」，而是机器可读的勾稽：同一期的净利润必须能滚进权益，间接法经营现金流必须能与现金科目变动对上。对不上，因子分子分母就不是同一个经济量。</p><h3 id="期间流量不是时点存量" tabindex="-1">期间流量不是时点存量 <a class="header-anchor" href="#期间流量不是时点存量" aria-label="Permalink to &quot;期间流量不是时点存量&quot;">​</a></h3><p>净利润、收入、经营现金流是<strong>期间</strong>量；总资产、账面权益、现金余额是<strong>时点</strong>量。数据库字段混用「最新年报总资产」与「上季净利润」是低级错误，不是风格问题。后课缩放应计、算账面市值，都先要求你分清这两类。</p><p><span class="marginnote">Compustat 的 AT、CEQ 是时点；NI、OANCF 是期间。Wind、CSMAR 同理。本课不讲 vendor 字段表，只钉身份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Penman 把勾稽写成两条主链，后课所有比率都从这里取数。</p><p>链一：利润表 → 权益变动 → 资产负债表。净利润减股利（及少数股东份额等）进入留存收益；期初股东权益加上本期综合收益与资本交易，得到期末权益。账面市值的「账面」取的是这条链上的权益，不是利润表上的某个流量。</p><p>链二：利润表 → 间接法现金流量表 → 现金。从净利润出发，加回折旧摊销减值等非现金费用，调整应收应付存货等营运资本变动，得到经营现金流；再加投资与筹资活动，三活动合计等于现金及等价物的净变动，从而闭合到资产负债表的现金科目。</p><p>身份一旦闭合，后课才能合法写 \\(Accruals \\approx NI - OCF\\)，才能把账面权益放进价值因子的分母。Fama–French 构造 HML 时用的 Compustat 账面权益，正是这条链上的存量，不是「最新利润的某种折现」。</p><p><span class="marginnote">数字实例：公司今年净利润 100 万、分红 30 万，若无其他综合收益与回购，期末留存收益应比期初多 70 万；若账上现金反而少了 20 万，间接法现金流也应算出 -20 万。三张表像齿轮一样互相咬合，咬合不上就说明某处科目或口径接错了。</span></p><p><span class="marginnote">直觉类比：净利润是「应该赚到多少」的观点，经营现金流是「实际收到多少」的事实，两者之差就是应计——挂在应收、存货等科目里。\\(Accruals \\approx NI - OCF\\) 因此可读作「利润里有多少还没变成钱」；应计占比越高，后续盈利质量越可疑。</span></p>',16)),(E(),s(A,null,{default:t(()=>[l(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20IS%5B%22%E5%88%A9%E6%B6%A6%E8%A1%A8%E6%9C%9F%E9%97%B4%E7%BB%A9%E6%95%88%22%5D%20--%3E%20RE%5B%22%E7%95%99%E5%AD%98%E6%94%B6%E7%9B%8A%22%5D%0A%20%20RE%20--%3E%20BS%5B%22%E8%B5%84%E4%BA%A7%E8%B4%9F%E5%80%BA%E8%A1%A8%E6%9D%83%E7%9B%8A%22%5D%0A%20%20IS%20--%3E%20CF%5B%22%E9%97%B4%E6%8E%A5%E6%B3%95%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20CF%20--%3E%20CASH%5B%22%E7%8E%B0%E9%87%91%E5%8F%8A%E7%AD%89%E4%BB%B7%E7%89%A9%22%5D%0A%20%20CASH%20--%3E%20BS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[e("实务库把科目投影成标准化字段。回测取的是两个时间戳：报告期结束日，以及市场第一次能读到该期数字的公告日。本课只要求你承认两者不同；"),n("a",{href:"/quant/pit-fundamentals"},"Point-in-time 基本面"),e("才把「当时能看到的版本」写成约束。勾稽检查是因子管道的单元测试：同一公司同一期，净利润应与权益变动表里的净利润行一致；间接法经营现金流与现金变动在调整后应闭合。闭合失败通常是合并范围、一次性项目或字段映射错误，不是「市场无效」。")],-1)),(E(),s(A,null,{default:t(()=>[l(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20END%5B%22%E6%8A%A5%E5%91%8A%E6%9C%9F%E7%BB%93%E6%9D%9F%E6%97%A5%22%5D%20--%3E%20PREP%5B%22%E5%85%AC%E5%8F%B8%E7%BC%96%E5%88%B6%E4%B8%8E%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20PREP%20--%3E%20ANN%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%3A%20%E5%B8%82%E5%9C%BA%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%AF%BB%E5%88%B0%22%5D%0A%20%20ANN%20--%3E%20DB%5B%22%E6%95%B0%E6%8D%AE%E5%BA%93%E5%85%A5%E5%BA%93%E6%97%A5%22%5D%0A%20%20DB%20--%3E%20OK%5B%22%E5%9B%9E%E6%B5%8B%E5%8F%96%E6%95%B0%E4%B8%8D%E6%97%A9%E4%BA%8E%E5%85%AC%E5%91%8A%E6%97%A5%22%5D%0A%20%20ANN%20-.%20%22%E7%94%A8%E7%BB%93%E6%9D%9F%E6%97%A5%E5%AF%B9%E9%BD%90%E4%BB%B7%E6%A0%BC%22%20.-%3E%20BAD%5B%22%E6%8F%90%E5%89%8D%E8%AF%BB%E5%88%B0%E6%95%B0%E5%AD%97%3A%20%E5%89%8D%E8%A7%86%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">后课质量因子、价值因子都默认你会先跑这条勾稽。身份错了，排序再精致也是在排错的数。</span></p><p>勾稽失败时不要用「以利润表为准」或「以现金流为准」悄悄改一个字段去闭合。先停下来查合并范围、货币单位、是否把母公司单体与合并表接在同一期。Fama–French 复制里账面权益对不上，多半是优先股、NCI 或负账面处理不一致，而不是市场把会计恒等式打破了。本课交给后课的，是一张能通过身份测试的宽表雏形，不是已经可交易的因子。</p><p><span class="marginnote">常见误区：把「报表对不上」当成数据商的 bug 强行凑平。真正的元凶常是口径：把母公司单体报表与合并报表混接、把年报与季度的科目同名对接、或忘了少数股东损益要剔除。先查口径，再怀疑数据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重讲分录，不对照 GAAP 与 IFRS 逐条差异。商誉、租赁资本化、合并少数股东、递延税是后面质量与分类课的缺口。本课也不构造 CAPM 或风险溢价；Fama–French 因子只在此借用「账面权益从哪张表来」这一句，构造细节交给<a href="/quant/fundamental-factor-source">基本面因子从哪张表来</a>。定价数学不再展开：风险中性测度已在随机分析课结束。</p><p>后课默认：三张表结构与两条主勾稽已读完；讨论任何基本面字段时，先问它是期间还是时点、来自哪张表。本课不引入可用日期，是故意把身份与时钟分开：身份错了，时钟再准也在对错误的数。随机分析课的测度与模拟到此不再展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定价课收到可算期望；本课换成可勾稽的公司状态表。</li><li>利润表绩效经留存收益进入资产负债表权益。</li><li>间接法现金流从净利润翻译现金，三活动合计等于现金变动。</li><li>期间量与时点量不能混缩放；可用日期尚未引入。</li><li>后课默认勾稽已闭合，再谈应计、PIT 与幸存者。</li><li>出处：Penman, <em>Financial Statement Analysis and Security Valuation</em> 第 3–5 章。</li></ul>',8))])}const _=o(d,[["render",m]]);export{F as __pageData,_ as default};
